 for(const [id,key] of [['rangeVin','vin'],['rangeVout','vout'],['rangePout','outputPower']])bindSelect(id,v=>explorer.filters[key]=v);
 bindSelect('rangeBreakdown',v=>explorer.breakdown=v);bindSelect('rangeMetric',v=>explorer.metric=v);
