 const selectPoint=(key,value)=>{const rows=orderedOperatingPoints(results.rows.filter(r=>r.combination===resultCombination)),current=rows.find(r=>r.waveformId===p.selectedOperatingPoint)||rows[0];const candidates=rows.filter(r=>sameCoordinate(r[key],Number(value))&&(key==='vin'||sameCoordinate(r.vin,current.vin))&&(key!=='outputPower'||sameCoordinate(r.vout,current.vout)));const next=candidates.find(r=>sameCoordinate(r.vout,current.vout)&&sameCoordinate(r.outputPower,current.outputPower))||candidates.find(r=>sameCoordinate(r.vout,current.vout))||candidates[0];if(next){p.selectedOperatingPoint=next.waveformId;selectedWave=next.waveformId;p.debugSelection=null;debugWaveIndex=null;saveLocal();}};
 for(const [id,key] of [['pointVin','vin'],['pointVout','vout'],['pointPout','outputPower']])bindSelect(id,v=>selectPoint(key,v));
 const inspect=(instanceId,combination,waveformId)=>{if(combination)resultCombination=Number(combination);if(waveformId)p.selectedOperatingPoint=waveformId;explorer.scope='point';explorer.pointTab='inspect';explorer.component=instanceId;const r=results.rows.find(r=>r.combination===resultCombination&&r.waveformId===p.selectedOperatingPoint),d=r?.devices.find(d=>d.instanceId===instanceId);if(d)p.sensitivitySettings={...(p.sensitivitySettings||{}),target:d.instanceId+':'+d.candidateId,waveformId:r.waveformId};render();};
