 click('addInstance',()=>{modal(`<div class="panel-head"><h2>Add component instance</h2><button class="ghost small" data-close>×</button></div><label>Type<select id="newInstanceType">${options(['MOSFET','Diode','Capacitor','Inductor'],'MOSFET')}</select></label><label>Name<input id="newInstanceName" placeholder="Q1 · high-side switch"></label><div class="toolbar"><button id="confirmInstance" class="primary">Add component</button></div>`);$('#confirmInstance').onclick=()=>{let type=$('#newInstanceType').value,i=makeInstance(type);i.candidates=[blankCandidate(type)];i.name=$('#newInstanceName').value.trim()||type+' '+(p.instances.filter(q=>q.type===type).length+1);p.instances.push(i);selectedInstance=i.id;selectedCandidate=i.candidates[0].id;$('#modal').close();changed(true);};});
