function run(screened=false){readiness=checkProject(p);if(readiness.errors.length){location.hash='checks';render();toast('Fix the highlighted inputs, then run again.');return;}if(screened!==true){if(screened==='auto'){startProjectionScreen();return;}modal(projectSummary(p)+'<div class="toolbar"><button id="confirmStudyRun" class="primary">Confirm & check characteristic queries</button><button data-close class="ghost">Return to setup</button></div>');$('#confirmStudyRun').onclick=()=>{$('#modal').close();startProjectionScreen();};return;}sensitivity=null;reportPreferences=null;if(worker)worker.terminate();setRunning(true);progressUpdate('Calculating component alternatives');$('#status').textContent='Validating models and computing alternatives…';worker=new Worker('worker.js?v=2.1.0',{type:'module'});worker.onmessage=e=>{if(e.data.progress!==undefined){progressUpdate('Calculating component alternatives',e.data.progress);$('#status').textContent=`Calculating unique alternatives · ${Math.round(e.data.progress*100)}%`;}else if(e.data.result){results=e.data.result;results.rows=orderedOperatingPoints(results.rows);worker.terminate();worker=null;setRunning(false);resultCombination=results.best?.combination||1;$('#status').textContent=`Analysis complete · ${results.combinationCount} combinations · ${results.errors.length} candidate/point failures`;render();toast(results.best?'Analysis complete. Results and exports are ready.':'Analysis completed with validation failures. Inspect results.');}else{worker.terminate();worker=null;setRunning(false);$('#status').textContent='Analysis stopped · '+e.data.error;toast(e.data.error);}};worker.onerror=e=>{setRunning(false);worker?.terminate();worker=null;toast('Calculation worker failed: '+e.message);};worker.postMessage({...p,operating:{...p.operating,projectionScreen:false}});}
async function readJSONorMAT(file){return file.name.toLowerCase().endsWith('.mat')?await parseMat(await file.arrayBuffer()):JSON.parse(await file.text());}
async function importWaves(files){let batch=[],failures=[];for(const file of files){try{let w;if(/\.(csv|txt)$/i.test(file.name))w=parseDelimited(await file.text(),file.name);else{const raw=await readJSONorMAT(file);if(raw.schemaVersion===1){throw Error('Use Open project for a project JSON');}if(raw.columns){w={id:uid('wave'),name:file.name,...raw};}else{let numeric=Object.entries(raw).filter(([,v])=>Array.isArray(v)&&v.length&&Array.isArray(v[0])&&v[0].every(Number.isFinite));if(!numeric.length)throw Error('No numeric matrix found. Export MATLAB tables using export_loss_tool_web.m');let [key,data]=numeric.length===1?numeric[0]:await chooseMatrix(numeric);if(data.length<2)throw Error('Matrix has too few rows');let headers=Array.from({length:data[0].length},(_,j)=>'Var'+(j+1));w={id:uid('wave'),name:file.name+' · '+key,columns:Object.fromEntries(headers.map((h,j)=>[h,data.map(row=>row[j])])),time:headers[0],units:{}};}}
 batch.push(w);}catch(e){failures.push(file.name+': '+e.message);}}if(failures.length){modal(`<h2>Batch import could not continue</h2><p>Resolve these files and import the batch again.</p><ul>${failures.map(e=>`<li>${esc(e)}</li>`).join('')}</ul><button class="ghost" data-close>Close</button>`);return;}try{const scan=scanWaveBatch(batch);if(scan.mismatches.length){modal(`<h2>Variable consistency check failed</h2><p>All files must contain the same variables. Column order can differ.</p>${table(['File','Missing variables'],scan.mismatches.map(w=>`<tr><td>${esc(w.name)}</td><td>${esc(w.missing.join(', '))}</td></tr>`))}<button class="ghost" data-close>Close</button>`);return;}const imported=await unitModal(batch);if(!imported)return;p.waveforms.push(...imported);selectedWave=imported[0].id;changed(true);toast(imported.length+' files imported with one shared units confirmation.');}catch(e){toast(e.message);}}
function chooseMatrix(entries){return new Promise(resolve=>{modal(`<div class="panel-head"><h2>Choose MAT variable</h2></div><select id="matrixVariable">${entries.map(([k,v],j)=>`<option value="${j}">${esc(k)} · ${v.length} × ${v[0].length}</option>`).join('')}</select><button class="primary" id="chooseMat">Import matrix</button>`);$('#chooseMat').onclick=()=>{let selected=entries[Number($('#matrixVariable').value)];$('#modal').close();resolve(selected);};$('#modal').addEventListener('cancel',()=>resolve(entries[0]),{once:true});});}
function unitModal(batch){return new Promise(resolve=>{let w=batch[0],keys=Object.keys(w.columns);modal(`<div class="panel-head"><h2>Confirm shared columns & units · ${batch.length} files</h2><button class="ghost small" id="cancelImport">Cancel</button></div><p class="caption">Consistency passed: all files have the same variables. Rename numeric MAT columns if needed. Choose time and confirm each variable’s unit once for the complete batch. Values are converted once to seconds, volts and amps.</p><label>Time column<select id="importTime">${options(keys,w.time)}</select></label>${table(['Column name','Unit'],keys.map((k,j)=>`<tr><td><input data-column="${j}" value="${esc(k)}"></td><td><select data-unit="${j}">${options(['s','ms','us','ns','V','mV','kV','A','mA','-'],w.units?.[k]|| (k===w.time?'s':/^i|current/i.test(k)?'A':'V'))}</select></td></tr>`))}<div class="toolbar"><button class="primary" id="confirmUnits">Import ${batch.length} waveforms</button></div>`);
 const cancel=()=>{$('#modal').close();resolve(null);};$('#cancelImport').onclick=cancel;$('#modal').addEventListener('cancel',()=>resolve(null),{once:true});$('#confirmUnits').onclick=()=>{try{let columns={},units={},renamed=[];keys.forEach((k,j)=>{const name=$(`[data-column="${j}"]`).value.trim();if(!name||name in columns)throw Error('Column names must be nonempty and unique');renamed.push(name);columns[name]=w.columns[k];units[name]=$(`[data-unit="${j}"]`).value;});let time=renamed[keys.indexOf($('#importTime').value)];if(!['s','ms','us','ns'].includes(units[time]))throw Error('Time column unit must be seconds, ms, us or ns');let out=batch.map(wave=>applyUnits({...wave,id:uid('wave'),columns:Object.fromEntries(keys.map((k,j)=>[renamed[j],wave.columns[k]]))},units,time));$('#modal').close();resolve(out);}catch(e){toast(e.message);}};});}
$('#waveFiles').onchange=e=>{importWaves([...e.target.files]);e.target.value='';};
$('#curveFiles').onchange=async e=>{let c=getCand();if(!c)return toast('Select a candidate first');for(const file of e.target.files){try{let raw=await readJSONorMAT(file),curves=[];if(raw.candidate||raw.candidates||(raw.curves&&raw.part)){alternativeImportDialog(raw);continue;}if(raw.curve)curves=[raw.curve];else if(raw.curves)curves=Array.isArray(raw.curves)?raw.curves:Object.values(raw.curves);else if(raw.characteristicId||raw.xName||raw.constant!==undefined)curves=[raw];else if(Array.isArray(raw))curves=raw;else throw Error('Select individual curve MAT files or a candidate/curve JSON');let converted=curves.map(cr=>canonicalCurve(cr)).map(cr=>({...cr,id:uid('curve')}));c.curves.push(...converted);changed(true);toast(converted.length+' characteristic(s) imported');}catch(err){toast(file.name+': '+err.message);}}e.target.value='';};
$('#projectFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;worker?.terminate();worker=null;setRunning(false);const reader=new FileReader();let loader=null,cancelled=false,rejectTask=null;progressOpen('Opening project',()=>{cancelled=true;reader.abort();loader?.terminate();rejectTask?.(Error('Project import cancelled'));progressClose();});try{progressUpdate('Reading file',0);const buffer=await new Promise((resolve,reject)=>{rejectTask=reject;reader.onprogress=v=>progressUpdate('Reading file',v.lengthComputable?v.loaded/v.total:undefined);reader.onerror=()=>reject(Error('Could not read this file'));reader.onabort=()=>reject(Error('Project import cancelled'));reader.onload=()=>resolve(reader.result);reader.readAsArrayBuffer(file);});if(cancelled)throw Error('Project import cancelled');progressUpdate('Parsing project');const imported=await new Promise((resolve,reject)=>{rejectTask=reject;loader=new Worker('worker.js?v=2.1.0',{type:'module'});loader.onmessage=event=>{if(event.data.stage){progressUpdate(event.data.stage);return;}if(event.data.error)reject(Error(event.data.error));else resolve(event.data);};loader.onerror=event=>reject(Error(event.message));loader.postMessage({task:'import-project',buffer,name:file.name},[buffer]);});if(cancelled)throw Error('Project import cancelled');progressUpdate('Opening workspace',1);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));explorer.combinations=null;explorer.filters={vin:'all',vout:'all',outputPower:'all'};p=imported.project;results=null;sensitivity=null;reportPreferences=null;projectionReview=null;readiness=imported.checks;selectedInstance=null;selectedCandidate=null;selectedWave=null;saveLocal();render();toast('Project loaded. Review input checks before analysis.');}catch(err){toast(err.message);}finally{loader?.terminate();progressClose();e.target.value='';}};
$('#imageFile').onchange=e=>{const file=e.target.files[0];if(!file)return;worker?.terminate();worker=null;setRunning(false);const reader=new FileReader();reader.onload=()=>{let im=new Image();im.onload=()=>{digit={image:im,imageData:reader.result,calibration:[],points:[],stage:'calibrate',zoom:1,curveId:digit.curveId,group:digit.group};render();};im.src=reader.result;};reader.readAsDataURL(file);e.target.value='';};
$('#projectName').onchange=e=>{p.name=e.target.value.trim()||'Untitled study';changed();};$('#openProject').onclick=()=>$('#projectFile').click();$('#saveProject').onclick=()=>download(nameSafe(p.name)+'.json',JSON.stringify({...p,engineVersion:ENGINE_VERSION},null,2));$('#run').onclick=run;$('#cancelRun').onclick=()=>{worker?.terminate();worker=null;setRunning(false);$('#status').textContent='Analysis cancelled';};
$('#demo').onclick=()=>{if(p.waveforms.length&&!confirm('Replace the current study with synthetic demo data? Download your project first if you need a copy.'))return;p=demoProject();selectedInstance=null;selectedCandidate=null;selectedWave=null;changed();location.hash='overview';render();run();};$('#newProject').onclick=()=>{if(p.waveforms.length&&!confirm('Start a new study? Download your current project first if you need a copy.'))return;p=emptyProject();selectedInstance=null;selectedCandidate=null;selectedWave=null;changed();location.hash='overview';render();};window.addEventListener('hashchange',render);render();if(p.waveforms.every(w=>w.demo)&&p.waveforms.length)run('auto');

function alternativeImportDialog(raw){const sources=raw.candidate?[raw.candidate]:raw.candidates||[raw];let sourceIndex=0;const current=getInst();let type=raw.componentType||raw.type||current?.type||'MOSFET';function draw(){if($('#modal').open)$('#modal').close();const source=sources[sourceIndex];if(!source||!Array.isArray(source.curves))throw Error('This file does not contain alternative characteristics');modal(`<div class="panel-head"><h2>Reuse alternative characteristics</h2><button data-close class="ghost">×</button></div><label>Part / alternative in file<select id="importSource">${sources.map((c,j)=>`<option value="${j}" ${j===sourceIndex?'selected':''}>${esc(c.part||'Alternative '+(j+1))}</option>`).join('')}</select></label><label>Component type<select id="importType" ${(raw.componentType||raw.type)?'disabled':''}>${options(['MOSFET','Diode','Capacitor','Inductor'],type)}</select></label><label>Destination<select id="importDestination">${current&&current.type===type?`<option value="new">New alternative in ${esc(current.name)}</option><option value="existing">Add characteristics to ${esc(getCand().part||'selected alternative')}</option>`:''}<option value="instance">New component</option></select></label><h3>Characteristics to import</h3>${source.curves.map((cr,j)=>`<label class="check"><input type="checkbox" data-import-characteristic="${j}" checked>${esc(cr.sourceId?characteristicName(cr.sourceId):cr.yName+' vs '+cr.xName)} · ${cr.iterations?.length||0} iterations</label>`).join('')}<p class="caption">Only the selected characteristics and their measured reference conditions are reused. Configure series/parallel counts, gate settings, enabled losses, thermal settings and waveform mappings yourself. Existing alternative settings are preserved.</p><button class="primary" id="confirmAlternativeImport">Import selected characteristics</button><button class="ghost" data-close>Cancel</button>`);$('#importSource').onchange=e=>{sourceIndex=Number(e.target.value);draw();};$('#importType').onchange=e=>{type=e.target.value;draw();};$('#confirmAlternativeImport').onclick=()=>{try{const indices=[...document.querySelectorAll('[data-import-characteristic]:checked')].map(el=>Number(el.dataset.importCharacteristic));const imported=importAlternative(raw,type,sourceIndex,indices),destination=$('#importDestination').value;let target=current,candidate;if(destination==='instance'){target=makeInstance(type);target.name=imported.part||type;target.candidates=[];}candidate=destination==='existing'?getCand():blankCandidate(type);if(destination!=='existing')candidate.part=imported.part;candidate.curves.push(...imported.curves);if(destination!=='existing')target.candidates.push(candidate);if(destination==='instance')p.instances.push(target);selectedInstance=target.id;selectedCandidate=candidate.id;subtab='curves';$('#modal').close();changed(true);toast(imported.curves.length+' characteristics imported. Configure the alternative settings before analysis.');}catch(error){toast(error.message);}};}draw();}
$('#componentFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{alternativeImportDialog(JSON.parse(await file.text()));}catch(error){toast(error.message);}finally{e.target.value='';}};
